import {levels,cells,holes,createWorld,snapshot,move,complete,step,settle,accessible,destinations,hint,isSpare,STEP} from './engine.mjs';
const $=s=>document.querySelector(s),ns='http://www.w3.org/2000/svg',colors=['#557f79','#c67d57','#c9a75d','#739381'];
let saved={};try{saved=JSON.parse(localStorage.getItem('screw-workshop-physics-v3')||'{}')||{}}catch{}
let done=new Set(Array.isArray(saved.done)?saved.done.filter(n=>Number.isInteger(n)&&n>=0&&n<levels.length):[]),index=Number.isInteger(saved.level)&&saved.level>=0&&saved.level<levels.length?saved.level:0,sim,history=[],selected=null,hintHole=null,frame=null,busy=false,plateNodes=[],pinNodes=[],holeNodes=[];
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function persist(){try{localStorage.setItem('screw-workshop-physics-v3',JSON.stringify({level:index,done:[...done]}))}catch{}}
function cancelMotion(){if(frame!==null)cancelAnimationFrame(frame);frame=null;busy=false}
function start(i){cancelMotion();index=i;sim=createWorld(levels[i]);settle(sim);history=[];selected=null;hintHole=null;persist();render();say(levels[i].tip)}
function say(t){$('#message').textContent=t}
function pos(el,h){el.style.left=cells[h].x/350*100+'%';el.style.top=cells[h].y/430*100+'%'}
function svgEl(name,attrs={}){const e=document.createElementNS(ns,name);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e}
function render(){const l=levels[index],board=$('#board');board.replaceChildren();plateNodes=[];pinNodes=[];holeNodes=[];$('#number').textContent=`PUZZLE ${String(index+1).padStart(2,'0')} / ${levels.length}`;$('#name').textContent=l.name;$('#moves').textContent=`${sim.moves} ${sim.moves===1?'move':'moves'}`;$('#undo').disabled=!history.length;$('#hint').disabled=false;
 const avail=destinations(sim),svg=svgEl('svg',{viewBox:'0 0 350 430','aria-hidden':'true',class:'physics-scene'});board.append(svg);
 for(const h of holes(l)){const c=cells[h];svg.append(svgEl('circle',{cx:c.x,cy:c.y,r:8,fill:'#473a2c',stroke:'#ddba85','stroke-width':1}));const b=document.createElement('button');b.className='hole physics-hole'+(selected!==null&&avail.includes(h)?' target':'')+(hintHole===h?' hinted':'');pos(b,h);b.setAttribute('aria-label',`${isSpare(l,h)?'Spare':'Board'} hole ${h+1}${sim.positions.includes(h)?', occupied':', empty'}`);b.disabled=!avail.includes(h);b.onclick=()=>place(h);board.append(b);holeNodes.push({h,el:b})}
 l.plates.forEach((_,p)=>{const body=sim.plates[p],L=body.plugin.length,g=svgEl('g',{'data-plate':p}),path=`M ${-L/2-18} -17 H ${L/2+18} V 17 H ${-L/2-18} Z M ${-L/2-10} -10 V 10 H ${-L/2+10} V -10 Z M ${L/2-10} -10 V 10 H ${L/2+10} V -10 Z`;
 const shape=svgEl('path',{d:path,fill:colors[p%colors.length],'fill-rule':'evenodd',stroke:'#e7e7cd','stroke-width':1.2,class:'material'});g.append(shape);
 for(const x of [-L/2,L/2])g.append(svgEl('rect',{x:x-10,y:-10,width:20,height:20,fill:'none',stroke:'#29443a','stroke-width':1.8,class:'material-hole'}));
 const label=svgEl('text',{x:0,y:3,'text-anchor':'middle',fill:'#ffffff70','font-size':8,'font-weight':700,'letter-spacing':2});label.textContent=String.fromCharCode(65+p);g.append(label);svg.append(g);plateNodes.push(g)});
 const label=document.createElement('div');label.className='storage-label';label.textContent='ONE SPARE · FIND THE HIDDEN WOOD HOLES';board.append(label);
 sim.positions.forEach((h,b)=>{const el=document.createElement('button');el.className='bolt'+(sim.removed&(1<<b)?' parked':'')+(selected===b?' selected':'');pos(el,h);el.style.zIndex=30;el.setAttribute('aria-label',`Screw ${b+1}${sim.removed&(1<<b)?', parked':`, plate ${String.fromCharCode(65+Math.floor(b/2))}`}`);el.setAttribute('aria-pressed',selected===b);el.onclick=()=>select(b);board.append(el);pinNodes.push(el)});draw();
 const win=$('#win');win.hidden=!complete(sim);if(!win.hidden){done.add(index);persist();win.innerHTML=`<span class="complete-mark">✓</span><h3>${index===levels.length-1?'A job well done.':'Nicely undone.'}</h3><p>${index===levels.length-1?'That’s the last puzzle. Nothing to claim, nothing to keep up with. Come back whenever you like.':`Every plate has fallen clear. ${sim.moves} moves, and not a clock in sight.`}</p><button class="primary" id="next">${index===levels.length-1?'Choose a puzzle':'Next puzzle →'}</button>`;$('#next').onclick=()=>index===levels.length-1?showLevels():start(index+1)}
}
function draw(){sim.plates.forEach((b,p)=>{plateNodes[p].setAttribute('transform',`translate(${b.position.x} ${b.position.y}) rotate(${b.angle*180/Math.PI})`);plateNodes[p].style.display=b.plugin.cleared?'none':''});pinNodes.forEach((el,b)=>{const visible=accessible(sim,b);el.disabled=!visible;el.style.visibility=visible?'visible':'hidden'});const left=sim.plates.filter(b=>!b.plugin.cleared).length,loose=sim.plates.filter((b,p)=>!b.plugin.cleared&&(sim.removed&(3<<(p*2)))===(3<<(p*2))).length;$('#remaining').textContent=`${left} plates left${loose?` · ${loose} loose`:''}`;$('#board').setAttribute('aria-busy','false');const liveTargets=destinations(sim);holeNodes.forEach(({h,el})=>{el.disabled=!liveTargets.includes(h);el.classList.toggle('available',!el.disabled);el.classList.toggle('target',selected!==null&&!el.disabled)});if(selected!==null&&!accessible(sim,selected)){selected=null;hintHole=null;pinNodes.forEach(el=>{el.classList.remove('selected');el.setAttribute('aria-pressed','false')});holeNodes.forEach(({el})=>el.classList.remove('target'));say('That screw is now covered by a moving plate. Choose an exposed screw.')}}
function afterMotion(){busy=false;frame=null;if(complete(sim))render();else draw();if(complete(sim))say('Every plate has physically cleared the board. Take a breather.');else if(!destinations(sim).length)say('No free holes. Undo the last move and try another screw.');else if(sim.plates.some((b,p)=>!b.plugin.cleared&&(sim.removed&(3<<(p*2)))===(3<<(p*2))))say('A loose plate is caught. Move a supporting screw or free the plate underneath.');else if(selected===null)say('Ready when you are. You can move screws while the pieces are moving, too.')}
function animate(){
 if(frame!==null)return;busy=true;
 if(reduced.matches){settle(sim,2400);draw();if(sim.settled)afterMotion();else frame=requestAnimationFrame(()=>{frame=null;animate()});return}
 let last=performance.now(),acc=0;function tick(now){acc+=Math.min(50,now-last);last=now;while(acc>=STEP&&!sim.settled){step(sim);acc-=STEP}draw();if(sim.settled){afterMotion();return}frame=requestAnimationFrame(tick)}frame=requestAnimationFrame(tick)
}
function select(b){if(complete(sim)||!accessible(sim,b))return;selected=selected===b?null:b;hintHole=null;render();say(selected===null?'Choose another screw when you’re ready.':destinations(sim).length?'Tap a glowing clear board hole. You can move screws while the pieces move.':'No clear parking holes right now. Wait for an opening or undo.')}
function place(h){if(complete(sim))return;if(selected===null){say('Tap an exposed silver screw first, then a glowing wood hole.');return}
 const before=snapshot(sim),next=move(sim,selected,h);if(!next){if(!accessible(sim,selected))selected=null;render();say('The pieces moved: that screw or hole is now covered. Choose an exposed screw and clear wood hole.');return}
 history.push(before);sim=next;selected=null;hintHole=null;render();say('Keep going—screws can move while the pieces swing and slide.');animate()
}
$('#undo').onclick=()=>{if(!history.length)return;cancelMotion();sim=createWorld(levels[index],history.pop());selected=null;hintHole=null;render();say('Restored the previous positions and momentum. Moving pieces continue from there.');if(!sim.settled)animate()};
function openDialog(title,html){$('#dialogtitle').textContent=title;$('#dialogbody').innerHTML=html;$('#dialog').showModal()}
$('#close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#restart').onclick=()=>{if(!sim.moves){start(index);return}openDialog('A fresh start?','<p>Restart this puzzle? Your other completed puzzles stay saved.</p><button class="primary" id="confirmrestart">Restart puzzle</button>');$('#confirmrestart').onclick=()=>{$('#dialog').close();start(index)}};
$('#hint').onclick=()=>{const h=hint(sim);if(h.b!==undefined){selected=h.b;hintHole=h.h;render()}say(h.text)};
function showLevels(){openDialog('Pick a puzzle',`<p>Ten physical assemblies. All available from the start.</p><div class="levelgrid">${levels.map((l,i)=>`<button data-level="${i}">${String(i+1).padStart(2,'0')} · ${l.name}<small>${done.has(i)?'✓ Completed':i===index?'Currently playing':'Ready whenever you are'}</small></button>`).join('')}</div>`);document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{$('#dialog').close();start(+b.dataset.level)})}$('#levels').onclick=showLevels;
$('#help').onclick=()=>openDialog('Real weight. Real obstacles.','<ol><li>Tap an exposed screw, then a glowing hole in <strong>clear wood</strong>. One spare hole sits above the assembly. More round holes are hidden beneath the plates.</li><li>With one screw left, a plate swings about that screw. Both square cutouts remain part of the plate.</li><li>With no screws left, the plate falls—but other plates and screw shafts can catch it. Plates can tip and slide against each other.</li><li>A loose plate is not cleared until it actually falls out below the board. Move its support to free it.</li></ol><p>You can move screws while pieces swing and slide. Exposed screws and clear board targets are checked at the instant you tap. A round board hole is reusable once the screw shaft and a small safety margin are clear—even if part of its rim is covered. An aligned plate cutout can receive a parked peg, but does not create a new hinge. Original hinges and newly parked solid pegs are different.</p><p>Hints follow a tested route and suggest undoing a deviation; other solutions can work. Undo and restart are always free, even mid-swing.</p><p>Original game and artwork. Physics: Matter.js 0.20.0, MIT license. No ads, purchases, timers, streaks, or random rewards.</p>');
$('#install').onclick=()=>openDialog('Keep the workshop handy.','<p>On iPhone, open this link in <strong>Safari</strong>, tap <strong>Share</strong>, then <strong>Add to Home Screen</strong>.</p><p>This is a web game, not an App Store download. Internet and site access may be needed to open it. Progress stays in this browser; clearing browser data removes it.</p>');
start(index);
